GCOL = [[230, 190, 150], [232, 132, 120], [226, 126, 32], [236, 206, 80], [140, 128, 136], [24, 30, 92], [40, 112, 24], [122, 74, 6]]


def hw10(r, g, b):
    """rgb 0..255 -> hardware 10-bit (Y with the 16/13 pre-scale, U = Cr, V = Cb)."""
    y = (0.299 * r + 0.587 * g + 0.114 * b) / 255.0
    cb = (b / 255.0 - y) / 1.772
    cr = (r / 255.0 - y) / 1.402
    Y = int(round(64 + y * 876 * 16.0 / 13.0))
    Y = max(64, min(940, Y))
    U = max(16, min(1008, int(round(512 + cr * 896))))
    V = max(16, min(1008, int(round(512 + cb * 896))))
    return Y, U, V


def write_pkg():
    L = ["-- Generated by abacus.py -- DO NOT EDIT.",
         "library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n",
         "package abacus_pkg is",
         "    type t_ab_knot is array (0 to 4095) of std_logic_vector(7 downto 0);",
         "    constant C_AB_KNOT : t_ab_knot := ("]
    flat = [v for row in KNOTS for v in row]
    L.append(",\n".join("        " + ", ".join('x"%02X"' % v for v in flat[j:j + 16]) for j in range(0, 4096, 16)) + ");")
    L.append("    type t_ab_pal is array (0 to 511) of std_logic_vector(31 downto 0);")
    L.append("    constant C_AB_PAL : t_ab_pal := (")
    words = []
    for r, g, b in PAL:
        Y, U, V = hw10(r, g, b)
        words.append((Y << 22) | (U << 12) | (V << 2))
    L.append(",\n".join("        " + ", ".join('x"%08X"' % v for v in words[j:j + 8]) for j in range(0, 512, 8)) + ");")
    L.append("    type t_ab_gl is array (0 to 255) of std_logic_vector(63 downto 0);")
    L.append("    constant C_AB_GL : t_ab_gl := (")
    words = []
    for c in range(256):
        w = 0
        for k in range(4):
            col = c + (1 if k >= 2 else 0)
            d7, j, wc, a, cl = GL[col][k % 2]
            w |= ((d7 << 9) | (j << 8) | (wc << 5) | (a << 3) | cl) << (16 * k)
        words.append(w)
    L.append(",\n".join("        " + ", ".join('x"%016X"' % v for v in words[j:j + 4]) for j in range(0, 256, 4)) + ");")
    gw = []
    for r, g, b in GCOL:
        Y, U, V = hw10(r, g, b)
        gw.append((Y << 20) | (U << 10) | V)
    L.append("    function f_ab_gc(c : unsigned(2 downto 0)) return std_logic_vector;")
    L.append("end package abacus_pkg;\n")
    L.append("package body abacus_pkg is")
    L.append("    function f_ab_gc(c : unsigned(2 downto 0)) return std_logic_vector is")
    L.append("    begin")
    L.append("        case to_integer(c) is")
    for k, v in enumerate(gw):
        L.append('            when %d => return "%s";' % (k, format(v, '030b')) if k < 7 else '            when others => return "%s";' % format(v, '030b'))
    L.append("        end case;")
    L.append("    end function;")
    L.append("end package body abacus_pkg;")
    with open(os.path.join(HERE, "abacus_pkg.vhd"), "w") as f:
        f.write("\n".join(L) + "\n")


if __name__ == "__main__":
    write_pkg()
    print("abacus_pkg.vhd written")
